document.getElementById('etapaSenha').addEventListener('submit', async function (ev) {
  ev.preventDefault();
  var btn = document.getElementById('btnEntrar');
  btn.disabled = true;
  alerta('');
  try {
    var d = await api('/api/login', {
      email: document.getElementById('email').value,
      senha: document.getElementById('senha').value
    });

    if (d.requer2FA) {
      tempToken = d.tempToken;
      mostrar('etapaCodigo');
      document.getElementById('codigo').focus();
      return;
    }
    if (d.configurar2FA) {
      var c = await api('/api/login/2fa/iniciar', { tempToken: d.tempToken });
      tempToken = c.tempToken;
      document.getElementById('qrImg').src = c.qr;
      document.getElementById('segredoTxt').textContent = c.segredo;
      mostrar('etapaCadastro');
      document.getElementById('codigoCad').focus();
