document.getElementById('salvar').addEventListener('click', async function () {
  var btn = this, aviso = document.getElementById('aviso');
  aviso.innerHTML = '';
  btn.disabled = true;
  try {
    var r = await fetch('/api/perfil', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        telefone: document.getElementById('telefone').value,
        ramal: document.getElementById('ramal').value,
        departamento: departamentoEscolhido(),
        cargo: document.getElementById('cargo').value,
      }),
    });
    var d = await r.json().catch(function () { return {}; });
    if (!r.ok) throw new Error(d.erro || 'Não foi possível salvar');
    if (EU.exigirPerfil) { location.href = '/'; return; }
    aviso.innerHTML = '<div class="aviso aviso-ok">Salvo.</div>';
  } catch (e) {
    aviso.innerHTML = '<div class="aviso aviso-erro">' + esc(e.message) + '</div>';
  } finally {
    btn.disabled = false;
  }
})

