document.getElementById('arquivo').addEventListener('change', async function () {
  var arq = this.files && this.files[0];
  if (!arq) return;
  var aviso = document.getElementById('aviso');
  aviso.innerHTML = '';
  try {
    var base64 = await reduzir(arq);
    var r = await fetch('/api/perfil/foto', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ tipo: 'image/jpeg', base64: base64 }),
    });
    var d = await r.json().catch(function () { return {}; });
    if (!r.ok) throw new Error(d.erro || 'Não foi possível enviar a foto');
    EU.temFoto = true;
    mostrarFoto(true);
  } catch (e) {
    aviso.innerHTML = '<div class="aviso aviso-erro">' + esc(e.message) + '</div>';
  } finally {
    this.value = '';
  }
})

