text:
achadas.map(function (p) {
    var retrato = p.temFoto
      ? '<img class="bolha" src="/api/foto/' + encodeURIComponent(p.id) + '" alt="">'
      : '<div class="bolha">' + esc(iniciais(p.nome)) + '</div>';

    var linhas = [];
    if (p.telefoneFormatado) {
      linhas.push('<div><span class="rot">Tel</span> <a href="tel:' + esc(p.telefone) + '">' +
                  esc(p.telefoneFormatado) + '</a></div>');
    }
    if (p.ramal) linhas.push('<div><span class="rot">Ramal</span> ' + esc(p.ramal) + '</div>');
    linhas.push('<div><a href="mailto:' + esc(p.email) + '">' + esc(p.email) + '</a></div>');

    // Quem ainda nao preencheu aparece do mesmo jeito, com o que se sabe. Some
    // da agenda seria pior: a pessoa existe e alguem pode precisar dela.
    var faltando = (!p.departamento && !p.cargo)
      ? '<div class="incompleto">cadastro ainda não preenchido</div>' : '';

    return '<div class="card pessoa">' + retrato +
      '<div class="dados">' +
        '<h3>' + esc(p.nome) + '</h3>' +
        '<p class="cargo">' + esc([p.cargo, p.departamento].filter(Boolean).join(' · ')) + '</p>' +
        '<div class="contato">' + linhas.join('') + '</div>' +
        faltando +
      '</div></div>';
  }).join('')

