MODULOS.map(function (m) {
    var marcado = Object.prototype.hasOwnProperty.call(atuais, m.id);
    // value = o que o modulo entende (vai gravado); texto = o que se le.
    var opcoes = m.papeis.map(function (p) {
      var valor = p.valor !== undefined ? p.valor : p;
      var rotulo = p.rotulo !== undefined ? p.rotulo : p;
      return '<option value="' + esc(valor) + '"' + (atuais[m.id] === valor ? ' selected' : '') + '>' + esc(rotulo) + '</option>';
    }).join('');
    return '<div class="modItem">' +
      '<input type="checkbox" id="mod_' + esc(m.id) + '" data-mod="' + esc(m.id) + '"' + (marcado ? ' checked' : '') + '>' +
      '<span><label for="mod_' + esc(m.id) + '">' + esc(m.nome) + '</label>' +
        '<small>' + esc(m.descricao || '') + '</small></span>' +
      '<select data-papel="' + esc(m.id) + '"' + (marcado ? '' : ' disabled') + '>' + opcoes + '</select>' +
    '</div>';
  }).join('')

