document.getElementById('btnSenha').addEventListener('click', async function () {
    var btn = this;
    var aviso = document.getElementById('avisoSenha');
    var nova = document.getElementById('sNova').value;
    aviso.innerHTML = '';

    if (nova.length < 8) {
      aviso.innerHTML = '<div class="aviso aviso-erro">A nova senha precisa ter ao menos 8 caracteres.</div>';
      return;
    }
    if (nova !== document.getElementById('sNova2').value) {
      aviso.innerHTML = '<div class="aviso aviso-erro">As duas senhas não conferem.</div>';
      return;
    }

    btn.disabled = true;
    try {
      var r = await fetch('/api/senha', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ atual: document.getElementById('sAtual').value, nova: nova })
      });
      var dados = await r.json().catch(function () { return {}; });
      if (!r.ok) throw new Error(dados.erro || 'Não foi possível salvar');
      location.reload();
    } catch (e) {
      aviso.innerHTML = '<div class="aviso aviso-erro">' + esc(e.message) + '</div>';
      btn.disabled = false;
    }
  })

